HAND = the 21 OpenPose hand point names: wrist, thumb_cmc, thumb_mcp, thumb_ip, thumb_tip, index_mcp, index_pip, index_dip, index_tip, middle_mcp, middle_pip, middle_dip, middle_tip, ring_mcp, ring_pip, ring_dip, ring_tip, pinky_mcp, pinky_pip, pinky_dip, pinky_tip.
const FINGER_UVW = { // per finger: its 4 points in hand coordinates [u, v, w]
  thumb: [[0.025,0.020,0.010],[0.050,0.035,0.015],[0.075,0.045,0.020],[0.095,0.050,0.020]],
